SELECT id,argMax(description,updated_at) description,argMax(primary_language,updated_at) language,argMax(license,updated_at) license,min(created_at) created_at FROM repo_info WHERE platform='AtomGit' AND id IN (SELECT DISTINCT repo_id FROM global_openrank WHERE type='Repo' AND platform='AtomGit' AND org_id=5162848 AND created_at>='2025-07-01' AND created_at<'2026-11-01') GROUP BY id FORMAT JSON